@php $catalog=$products->map(fn($p)=>['id'=>$p->id,'name'=>$p->name,'sku'=>$p->sku,'units'=>$p->productUnits->where('can_purchase',true)->map(fn($u)=>['id'=>$u->unit_id,'name'=>$u->unit->name,'symbol'=>$u->unit->symbol,'rate'=>(float)$u->conversion_rate])->values()])->values(); @endphp
<div class="mb-6"><a class="text-sm text-slate-500" href="{{ route('purchases.index') }}">← Purchases</a><h1 class="mt-2 font-serif text-3xl text-ink">Receive a purchase</h1><p class="text-sm text-slate-500">Landed cost is allocated by invoice line value; supplier due excludes extra costs.</p></div><form method="post" action="{{ route('purchases.store') }}" x-data='purchaseForm(@json($catalog))'>@csrf<section class="card p-6"><div class="grid gap-5 md:grid-cols-2 xl:grid-cols-4"><div><label>Supplier *</label><select class="w-full" name="supplier_id" required><option value="">Select supplier</option>@foreach($suppliers as $s)<option value="{{ $s->id }}">{{ $s->name }}</option>@endforeach</select></div><div><label>Store *</label><select class="w-full" name="store_id" required>@foreach($stores as $s)<option value="{{ $s->id }}">{{ $s->name }}</option>@endforeach</select></div><div><label>Supplier invoice no.</label><input class="w-full" name="supplier_invoice_no"></div><div><label>Reference</label><input class="w-full" name="reference_no"></div><div><label>Purchase date *</label><input class="w-full" type="date" name="purchase_date" value="{{ now()->toDateString() }}" required></div><div><label>Due date</label><input class="w-full" type="date" name="due_date"></div><div><label>Extra / landed cost</label><input class="w-full" type="number" min="0" step="0.01" name="extra_cost_total" x-model.number="extra"></div><div><label>Notes</label><input class="w-full" name="notes"></div></div></section><section class="card mt-5 overflow-hidden"><div class="flex items-center justify-between p-5"><div><h2 class="font-serif text-xl">Purchase lines</h2><p class="text-xs text-slate-400">Quantities are converted to each product’s base unit.</p></div><button type="button" class="btn-soft" @click="add()">+ Add line</button></div><div class="overflow-x-auto"><table><thead><tr><th>Product</th><th>Purchase unit</th><th>Qty</th><th>Supplier unit cost</th><th>Discount</th><th>Tax</th><th>Base preview</th><th>Total</th><th></th></tr></thead><tbody><template x-for="(row,i) in rows" :key="i"><tr><td><select class="min-w-56" :name="`items[${i}][product_id]`" x-model.number="row.product_id" @change="productChanged(row)" required><option value="">Select product</option><template x-for="p in products"><option :value="p.id" x-text="`${p.name} · ${p.sku}`"></option></template></select></td><td><select class="min-w-32" :name="`items[${i}][unit_id]`" x-model.number="row.unit_id" required><template x-for="u in units(row)"><option :value="u.id" x-text="u.symbol"></option></template></select></td><td><input class="w-28" type="number" min="0.000001" step="0.000001" :name="`items[${i}][quantity]`" x-model.number="row.quantity" required></td><td><input class="w-36" type="number" min="0" step="0.0001" :name="`items[${i}][supplier_unit_cost]`" x-model.number="row.cost" required></td><td><input class="w-28" type="number" min="0" step="0.01" :name="`items[${i}][discount_amount]`" x-model.number="row.discount"></td><td><input class="w-28" type="number" min="0" step="0.01" :name="`items[${i}][tax_amount]`" x-model.number="row.tax"></td><td class="text-xs" x-text="`${base(row).toFixed(6)} base`"></td><td class="font-semibold" x-text="`Rs. ${money(total(row))}`"></td><td><button type="button" class="text-red-500" @click="rows.splice(i,1)" :disabled="rows.length===1">×</button></td></tr></template></tbody></table></div><div class="flex justify-end border-t border-slate-100 p-5"><div class="w-80 space-y-2 text-sm"><div class="flex justify-between"><span>Supplier invoice total</span><strong>Rs. <span x-text="money(supplierTotal)"></span></strong></div><div class="flex justify-between"><span>Extra cost</span><strong>Rs. <span x-text="money(extra)"></span></strong></div><div class="flex justify-between border-t pt-2 text-base"><span>Inventory landed value</span><strong>Rs. <span x-text="money(supplierTotal+(Number(extra)||0))"></span></strong></div></div></div></section><div class="mt-6 flex justify-end gap-3"><a class="btn-soft" href="{{ route('purchases.index') }}">Cancel</a><button class="btn-teal">Receive & update stock</button></div></form>
@push('scripts')<script>function purchaseForm(products){return{products,extra:0,rows:[{product_id:'',unit_id:'',quantity:1,cost:0,discount:0,tax:0}],add(){this.rows.push({product_id:'',unit_id:'',quantity:1,cost:0,discount:0,tax:0})},product(row){return this.products.find(p=>p.id==row.product_id)},units(row){return this.product(row)?.units||[]},productChanged(row){row.unit_id=this.units(row)[0]?.id||''},base(row){let u=this.units(row).find(u=>u.id==row.unit_id);return (Number(row.quantity)||0)*(Number(u?.rate)||0)},total(row){return Math.max(0,(Number(row.quantity)||0)*(Number(row.cost)||0)-(Number(row.discount)||0)+(Number(row.tax)||0))},get supplierTotal(){return this.rows.reduce((s,r)=>s+this.total(r),0)},money(v){return Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}}}</script>@endpush @endsection
